class BridgeWorkingTaskState {
  final String documentEditSummary;

  const BridgeWorkingTaskState({required this.documentEditSummary});

  @override
  int get hashCode => documentEditSummary.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeWorkingTaskState &&
          runtimeType == other.runtimeType &&
          documentEditSummary == other.documentEditSummary;
}

class BridgeWorktreeFailureCause {
  final BridgeWorktreeFailureCauseKind kind;
  final String message;
  final String? args;
  final int? exitCode;
  final String? stderr;

  const BridgeWorktreeFailureCause({
    required this.kind,
    required this.message,
    this.args,
    this.exitCode,
    this.stderr,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      message.hashCode ^
      args.hashCode ^
      exitCode.hashCode ^
      stderr.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeWorktreeFailureCause &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          message == other.message &&
          args == other.args &&
          exitCode == other.exitCode &&
          stderr == other.stderr;
}

enum BridgeWorktreeFailureCauseKind {
  invalidRepoRoot,
  unsafeBranch,
  gitLaunchFailed,
  gitTimedOut,
  gitExited,
  gitStatusUnknown,
  io,
  disabled,
  operationAndCleanupFailed,
}

class RuntimeSnapshot {
  final BigInt revision;
  final BridgeRuntimeState state;
  final List<BridgeActiveTurn> activeTurns;

  const RuntimeSnapshot({
    required this.revision,
    required this.state,
    required this.activeTurns,
  });

  @override
  int get hashCode => revision.hashCode ^ state.hashCode ^ activeTurns.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RuntimeSnapshot &&
          runtimeType == other.runtimeType &&
          revision == other.revision &&
          state == other.state &&
          activeTurns == other.activeTurns;
}
